import { Injectable } from "@angular/core";
import { SuperService } from "./super.service";
import { Usuario } from "../models/usuario";
import { firstValueFrom } from "rxjs";
import { StandarResponse } from "../services/http.service";

@Injectable({
    providedIn:'root'
})
export class UsuarioService extends SuperService<Usuario> {
    protected model = 'usuarios';
    protected columns: (keyof Usuario)[] = [
        'name',
        'email',
        'rfc',
        'password',
        'user_type',
        'email_verified_at',
        'deleted_at',
        'created_at',
        'updated_at'
    ]

    /**
     * Crea un nuevo usuario con un rol asignado
     */
    public async createWithRole(userData: Partial<Usuario>, roleName: string): Promise<Usuario | undefined> {
        const dataWithRole = {
            ...userData,
            role: roleName
        };

        return this.new(dataWithRole);
    }

    /**
     * Obtiene usuarios con sus roles y permisos cargados
     */
    public async getUsersWithRoles(): Promise<Usuario[]> {
        return this.all(['roles', 'roles.permissions', 'permissions']);
    }

    /**
     * Obtiene un usuario con sus roles y permisos
     */
    public async getUserWithRoles(id: number): Promise<Usuario | undefined> {
        return this.find(id, ['roles', 'roles.permissions', 'permissions']);
    }

    
    /**
     * Resets the user's password using the provided token and new password.
     * @param token The password reset token.
     * @param password The new password.
     * @param password_confirmation The password confirmation.
     */
    public async resetPassword(token: string, password: string, password_confirmation: string): Promise<StandarResponse> {
        const url = 'api/reset-password';
        return firstValueFrom(this.api.post(url, { token, password, password_confirmation }));
    }

     /**
     * Sends a password reset link to the given email address.
     * @param rfc The user's RFC.
     */
   public async sendPasswordResetLink(rfc: string): Promise<StandarResponse> {
        const url = 'api/forgot-password';
        
        return firstValueFrom(
            this.api.post<StandarResponse>(url, { rfc })
        );
    }
}